export class Soundtrack{
 constructor(){this.ctx=null;this.enabled=true;this.voiceEnabled=true;this.track=null;this.score=null;this.cursor=0;this.origin=0;this.loop=0;this.timer=null;this.voice=null;this.loaded=new Map();this.pending=0;this.fail=false}
 async unlock(){try{this.ctx??=new (window.AudioContext||window.webkitAudioContext)();if(!this.master){this.master=this.ctx.createGain();this.master.gain.value=.26;this.master.connect(this.ctx.destination);this.music=this.ctx.createGain();this.music.gain.value=.48;this.music.connect(this.master);this.fx=this.ctx.createGain();this.fx.connect(this.master);this.noise=this.ctx.createBuffer(1,this.ctx.sampleRate,this.ctx.sampleRate);const a=this.noise.getChannelData(0);for(let i=0;i<a.length;i++)a[i]=Math.random()*2-1}this.ctx.resume().catch(()=>{this.fail=true});return true}catch{this.fail=true;return false}}
 async play(name){if(this.track===name&&this.timer)return;this.stop();this.track=name;const token=++this.pending;try{let score=this.loaded.get(name);if(!score){const r=await fetch(`assets/music/${name}.json`);if(!r.ok)throw Error();score=await r.json();this.loaded.set(name,score)}if(token!==this.pending)return;this.score=score;if(!await this.unlock())return;this.origin=this.ctx.currentTime+.1;this.cursor=0;this.loop=0;this.timer=setInterval(()=>this.schedule(),80);this.schedule()}catch{this.fail=true}}
 stop(){clearInterval(this.timer);this.timer=null;this.score=null;this.pending++;if(this.music){this.music.disconnect();this.music=this.ctx.createGain();this.music.gain.value=.48;this.music.connect(this.master)}}
 schedule(){if(!this.score||!this.ctx||this.ctx.state!=='running')return;const s=this.score, beat=60/s.bpm;while(true){const e=s.events[this.cursor],at=this.origin+(e[0]+this.loop*s.beats)*beat;if(at>this.ctx.currentTime+.18)break;if(at>=this.ctx.currentTime-.02)this.note(e,Math.max(at,this.ctx.currentTime),beat);this.cursor++;if(this.cursor>=s.events.length){this.cursor=0;this.loop++}}}
 note([,dur,pitch,ch,vel],t,beat){if(!this.enabled)return;const c=this.ctx,g=c.createGain(),length=dur*beat,amp=vel/127;g.connect(this.music);if(ch===9){const n=pitch; if([36,41].includes(n)){let o=c.createOscillator();o.frequency.setValueAtTime(n===36?125:170,t);o.frequency.exponentialRampToValueAtTime(48,t+.15);g.gain.setValueAtTime(amp*.55,t);g.gain.exponentialRampToValueAtTime(.001,t+.2);o.connect(g);o.start(t);o.stop(t+.22)}else if([80,81,67].includes(n)){let o=c.createOscillator();o.type='sine';o.frequency.value=n===67?930:n===80?5100:6800;g.gain.setValueAtTime(amp*.10,t);g.gain.exponentialRampToValueAtTime(.001,t+(n===81?.18:.045));o.connect(g);o.start(t);o.stop(t+.2)}else{let o=c.createBufferSource(),f=c.createBiquadFilter();o.buffer=this.noise;f.type='highpass';f.frequency.value=n===39?1200:2000;g.gain.setValueAtTime(amp*.2,t);g.gain.exponentialRampToValueAtTime(.001,t+.09);o.connect(f);f.connect(g);o.start(t);o.stop(t+.1)}return}
 const f=440*2**((pitch-69)/12);g.gain.setValueAtTime(0,t);g.gain.linearRampToValueAtTime(amp*(ch===3?.15:.055),t+.015);g.gain.setValueAtTime(amp*(ch===3?.1:.045),t+Math.max(.02,length*.7));g.gain.exponentialRampToValueAtTime(.0001,t+length+.07);let harmonics=ch===0?[1,.38,.18,.12,.07]:ch===1?[1,.1,.04]:ch===2?[1,.26,.13,.07]:[1,.25];for(let h=0;h<harmonics.length;h++){let o=c.createOscillator(),v=c.createGain();o.frequency.value=f*(h+1);if(ch===0)o.detune.value=h%2?4:-3;v.gain.value=harmonics[h];o.connect(v);v.connect(g);o.start(t);o.stop(t+length+.08)}}
 toggle(){this.enabled=!this.enabled;if(this.master)this.master.gain.setTargetAtTime(this.enabled?.26:0,this.ctx.currentTime,.06);if(!this.enabled)this.voice?.pause();return this.enabled}
 effect(kind){if(!this.ctx||!this.enabled)return;const c=this.ctx,t=c.currentTime,seq={jump:[420,660],collect:[660,830,990],switch:[300,450,600],bump:[130,85],throw:[560,270],win:[523,659,784,1046]}[kind]||[400];seq.forEach((f,i)=>{const o=c.createOscillator(),g=c.createGain();o.type='triangle';o.frequency.value=f;g.gain.setValueAtTime(.1,t+i*.055);g.gain.exponentialRampToValueAtTime(.001,t+i*.055+.12);o.connect(g);g.connect(this.fx);o.start(t+i*.055);o.stop(t+i*.055+.13)})}
 speak(id){this.voice?.pause();if(!this.enabled||!this.voiceEnabled)return;this.voice=new Audio(`assets/voices/${id}.m4a`);this.voice.volume=.85;if(this.music)this.music.gain.setTargetAtTime(.15,this.ctx.currentTime,.08);const restore=()=>{if(this.music)this.music.gain.setTargetAtTime(.48,this.ctx.currentTime,.2)};this.voice.onended=restore;this.voice.onerror=restore;this.voice.play().catch(restore)}
 pause(){this.voice?.pause();this.ctx?.suspend()}
 resume(){this.ctx?.resume()}
}
